import{_ as r,o as a,c as d,a2 as i}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Симбиотический Трудовой Закон","description":"","frontmatter":{},"headers":[],"relativePath":"ru/41-共生劳动法.md","filePath":"ru/41-共生劳动法.md"}'),l={name:"ru/41-共生劳动法.md"};function e(o,t,n,s,h,b){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="симбиотическии-трудовои-закон" tabindex="-1">Симбиотический Трудовой Закон <a class="header-anchor" href="#симбиотическии-трудовои-закон" aria-label="Permalink to &quot;Симбиотический Трудовой Закон&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>41</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Симбиотический труд, Больше труда больше награды, Трудовые права, Совместный подряд, Антиэксплуатация</td></tr></tbody></table><h2 id="i-цель-законодательства-и-основные-принципы" tabindex="-1">I. Цель законодательства и основные принципы <a class="header-anchor" href="#i-цель-законодательства-и-основные-принципы" aria-label="Permalink to &quot;I. Цель законодательства и основные принципы&quot;">​</a></h2><p><em>Симбиотический Трудовой Закон</em> — один из ключевых законов правовой системы Симбиотической Цивилизации Якоря, стоящий в одном ряду с <em>Симбиотической Конституцией</em>. Он направлен на регулирование всех видов труда и вклада во Вселенной Хэнъюань, установление распределительного порядка «больше труда, больше награды; самопроизрастание и саморазвитие» и искоренение на правовом уровне почвы для хищнической эксплуатации.</p><p>Настоящий Закон устанавливает следующие основные принципы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Достоинство труда</td><td>Весь законный труд защищён законом; личное достоинство трудящихся не должно нарушаться</td></tr><tr><td>Больше труда — больше награды</td><td>Вознаграждение за труд напрямую связано с величиной вклада; чем больше вклад, тем выше доход; получение без труда запрещено</td></tr><tr><td>Добровольный труд</td><td>Принудительный труд и рабство запрещены; трудящиеся имеют право свободно выбирать содержание и способ труда</td></tr><tr><td>Справедливое вознаграждение</td><td>Равная оплата за равный труд; дискриминация в оплате по признаку расы, культивации или происхождения запрещена</td></tr><tr><td>Гарантия труда</td><td>Государство и цивилизация обязаны обеспечить трудящимся безопасную трудовую среду и базовое социальное обеспечение</td></tr><tr><td>Симбиотическое сотрудничество</td><td>Поощряется сотрудничество и взаимопомощь между трудящимися; против недобросовестной конкуренции и игр с нулевой суммой</td></tr></tbody></table><h2 id="ii-основные-права-трудящихся" tabindex="-1">II. Основные права трудящихся <a class="header-anchor" href="#ii-основные-права-трудящихся" aria-label="Permalink to &quot;II. Основные права трудящихся&quot;">​</a></h2><p>Симбиотический Трудовой Закон предоставляет всем формам жизни, обладающим способностью к труду во Вселенной Хэнъюань, следующие права:</p><ol><li><strong>Право на равное трудоустройство</strong>: никакая жизнь не должна подвергаться дискриминации при поиске работы и трудоустройстве по признаку расы, культивации, происхождения, пола и т.д.</li><li><strong>Право свободного выбора профессии</strong>: трудящиеся имеют право выбирать профессию, должность и место работы по собственному желанию и способностям, а также право менять профессию в соответствии с законом.</li><li><strong>Право на разумное вознаграждение</strong>: трудящиеся имеют право получать вознаграждение, соответствующее их трудовому вкладу; вознаграждение не должно быть ниже минимального гарантированного стандарта, установленного цивилизацией.</li><li><strong>Право на отдых и отпуск</strong>: трудящиеся имеют право на разумный режим рабочего времени и регулярные отпуска; безграничное продление рабочего времени запрещено.</li><li><strong>Право на безопасность труда</strong>: трудящиеся имеют право трудиться в безопасной и гигиеничной среде; работодатели обязаны обеспечивать условия охраны труда, соответствующие стандартам.</li><li><strong>Право на профессиональное обучение</strong>: трудящиеся имеют право получать профессиональную подготовку и культивационные наставления; работодатели и государство обязаны предоставлять учебные ресурсы.</li><li><strong>Право на объединение и переговоры</strong>: трудящиеся имеют право создавать или вступать в ассоциации трудящихся в соответствии с законом, а также право защищать свои интересы через коллективные переговоры.</li><li><strong>Право на обжалование и защиту</strong>: при нарушении трудовых прав трудящиеся имеют право подавать жалобы и иски в органы трудового арбитража и Симбиотический Суд.</li></ol><h2 id="iii-юридическое-закрепление-механизма-совместного-подряда" tabindex="-1">III. Юридическое закрепление Механизма Совместного Подряда <a class="header-anchor" href="#iii-юридическое-закрепление-механизма-совместного-подряда" aria-label="Permalink to &quot;III. Юридическое закрепление Механизма Совместного Подряда&quot;">​</a></h2><p>Механизм Совместного Подряда — ключевая система распределения ресурсов Симбиотической Цивилизации Якоря; <em>Симбиотический Трудовой Закон</em> закрепляет её в юридической форме:</p><ul><li><strong>Субъекты подряда</strong>: любое существо, обладающее способностью к труду, может быть субъектом подряда; подряжать могут как индивиды, так и коллективы.</li><li><strong>Содержание подряда</strong>: включает, но не ограничивается освоением культивационных ресурсов, обслуживанием плоскостей, передачей знаний, технологическими разработками, общественными услугами и другими областями.</li><li><strong>Срок подряда</strong>: определяется характером содержания подряда; краткосрочный подряд — от одного до трёх лет, долгосрочный — от пяти до двадцати лет, по истечении срока возможен переподряд.</li><li><strong>Распределение доходов</strong>: доход подрядчика напрямую связан с результатом; часть результата отчисляется в общественный фонд накопления, остальное принадлежит подрядчику.</li><li><strong>Механизм выхода</strong>: подрядчик имеет право выйти из подряда, предварительно уведомив в разумный срок; он не должен быть принудительно связан подрядными отношениями.</li><li><strong>Разрешение споров</strong>: подрядные споры в приоритетном порядке разрешаются трудовым арбитражем; при несогласии с решением арбитража можно подать иск в Симбиотический Суд.</li></ul><h2 id="iv-специальная-охрана-труда" tabindex="-1">IV. Специальная охрана труда <a class="header-anchor" href="#iv-специальная-охрана-труда" aria-label="Permalink to &quot;IV. Специальная охрана труда&quot;">​</a></h2><p>Учитывая особые потребности различных форм жизни во Вселенной Хэнъюань, настоящий Закон устанавливает систему специальной охраны труда:</p><table tabindex="0"><thead><tr><th>Охраняемая группа</th><th>Специальные меры охраны</th></tr></thead><tbody><tr><td>Начинающие культиваторы</td><td>Нельзя назначать высокорисковый труд сверх их возможностей; обязательно наставничество</td></tr><tr><td>Женские существа в период беременности и родов</td><td>Право на оплачиваемый отпуск по беременности не менее шести месяцев; в период кормления нельзя назначать высокоинтенсивный труд</td></tr><tr><td>Инвалиды и пострадавшие существа</td><td>Право на разумную корректировку рабочего места и гарантии безбарьерной трудовой среды</td></tr><tr><td>Трудящиеся иных рас</td><td>Работодатели обязаны уважать физиологические особенности и культурные обычаи иных рас и предоставлять адаптированные условия труда</td></tr><tr><td>Пожилые трудящиеся</td><td>По достижении определённого возраста могут подать заявление об уменьшении интенсивности труда или переходе на консультативные должности</td></tr></tbody></table><h2 id="v-юридическая-ответственность-и-гарантии-исполнения" tabindex="-1">V. Юридическая ответственность и гарантии исполнения <a class="header-anchor" href="#v-юридическая-ответственность-и-гарантии-исполнения" aria-label="Permalink to &quot;V. Юридическая ответственность и гарантии исполнения&quot;">​</a></h2><p>Работодатели, нарушившие положения настоящего Закона, в зависимости от тяжести обстоятельств несут следующую ответственность:</p><ol><li>Выплата трудящемуся причитающегося вознаграждения и компенсации (компенсация в размере от одного до трёхкратного размера задолженности).</li><li>Предписание об устранении нарушений в срок; при неустранении в срок — штраф.</li><li>При серьёзных обстоятельствах — аннулирование лицензии и запрет ответственным лицам заниматься управленческой деятельностью в течение определённого срока.</li><li>При наличии состава преступления — привлечение к уголовной ответственности в соответствии с законом.</li></ol><p>Государство создаёт органы инспекции труда, отвечающие за надзор и проверку соблюдения трудового законодательства работодателями. Ассоциации трудящихся имеют право представлять трудящихся при инспекции труда и коллективных переговорах.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Симбиотический Трудовой Закон</em> — правовой носитель философии «больше труда, больше награды» Симбиотической Цивилизации Якоря. Он превращает труд из объекта эксплуатации в уважаемое право, а распределение — из хищнического присвоения в вознаграждение по вкладу, закладывая прочную трудовую основу для совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>06-多劳多得分配原理 (Принципы Распределения Больше Труда Больше Награды)</li><li>22-资源分配联产承包机制 (Механизм Совместного Подряда Распределения Ресурсов)</li><li>42-消费者保护法 (Закон о Защите Прав Потребителей)</li></ul>',23)])])}const u=r(l,[["render",e]]);export{g as __pageData,u as default};
